package com.mandu.liquiddialer
import androidx.compose.ui.test.*
import androidx.compose.ui.semantics.SemanticsActions
import androidx.compose.ui.text.TextLayoutResult
import com.mandu.liquiddialer.data.*
import com.mandu.liquiddialer.ui.*
import kotlinx.coroutines.runBlocking
import org.junit.*
import org.junit.Assert.*
import org.junit.runner.RunWith
import org.robolectric.RobolectricTestRunner
import org.robolectric.annotation.*
abstract class ConverterLargeResultFixture:HistoryOptionsFixture(){
 @Before fun resetLarge(){large(false)}
 @After fun cleanLarge(){large(false)}
 protected fun large(on:Boolean=true){runBlocking{ctx.repo.set(K.converterLargeResult,on)};await{LdApp.settings.value.converterLargeResult==on};rule.waitForIdle()}
 protected fun height(tag:String)=rule.onNodeWithTag(tag,true).getUnclippedBoundsInRoot().let{(it.bottom-it.top).value}
 protected fun full(tag:String){move(tag);val out=mutableListOf<TextLayoutResult>();rule.onNodeWithTag(tag,true).performSemanticsAction(SemanticsActions.GetTextLayoutResult){it(out)};assertTrue("No layout for $tag",out.isNotEmpty());out.forEach{layout->assertEquals("Full text laid out for $tag",layout.layoutInput.text.length,layout.getLineEnd(layout.lineCount-1));for(i in 0 until layout.lineCount){assertFalse("No ellipsis for $tag",layout.isLineEllipsized(i));assertTrue("Line right edge for $tag",layout.getLineRight(i)<=layout.size.width+1f);assertTrue("Line bottom for $tag",layout.getLineBottom(i)<=layout.size.height+1f)}}}
 protected fun verify(r:CallConverter.Result){rule.onNodeWithTag("converter_result_source",true).assertTextEquals("${r.input} ${r.from.label}");if(LdApp.settings.value.converterLargeResult){rule.onNodeWithTag("converter_value",true).assertTextEquals("= ${r.value}");rule.onNodeWithTag("converter_result_unit",true).assertTextEquals(r.to.label);full("converter_result_unit")}else rule.onNodeWithTag("converter_value",true).assertTextEquals("= ${r.value} ${r.to.label}");full("converter_value");full("converter_result_source");full("converter_result_rounding")}
}
@RunWith(RobolectricTestRunner::class) @Config(sdk=[34],qualifiers="w360dp-h800dp-xhdpi") @GraphicsMode(GraphicsMode.Mode.NATIVE)
class ConverterLargeResultUiTest:ConverterLargeResultFixture(){
 @Test fun defaultOffReversibleCurrentResultOnly(){assertFalse(LdSettings().converterLargeResult);direct();input("converter_input","2.5");hit("converter_convert");val old=height("converter_result_source");val expected=CallConverter.convert("2.5","m","ft");verify(expected);move("converter_result");saveShot(rule,"CONV524-day-off");large();await{height("converter_result_source")>old};verify(expected);move("converter_result");saveShot(rule,"CONV524-day-on");rule.onNodeWithTag("converter_history_count",true).assertTextEquals("Session history: 1 / 10");large(false);await{height("converter_result_source")==old};verify(expected)}
 @Test fun allCategoriesKeepExactValuesAndRounding(){direct();large();for(kind in CallConverter.Kind.entries){hit("converter_kind_${kind.name.lowercase()}");val units=CallConverter.of(kind);val raw=if(kind==CallConverter.Kind.TEMPERATURE)"-40"else"2.5";input("converter_input",raw);hit("converter_convert");verify(CallConverter.convert(raw,units[0].id,units[1].id))};rule.onNodeWithTag("converter_history_count",true).assertTextEquals("Session history: 5 / 10");assertNull(org.robolectric.Shadows.shadowOf(rule.activity).nextStartedActivity)}
 @Test fun tableHistoryAndTypedInputSurvive(){start();hit("converter_table_make");val tableHeight=height("converter_table_value_ft");unfold();val historyHeight=height("converter_history_0");large();value().assertTextEquals("2");rule.onNodeWithTag("converter_table_value_ft",true).assertTextEquals(CallConverter.convert("2","m","ft").value);assertEquals(tableHeight,height("converter_table_value_ft"),0f);assertEquals(historyHeight,height("converter_history_0"),0f);rule.onNodeWithTag("converter_history_count",true).assertTextEquals("Session history: 2 / 10");large(false);assertEquals(historyHeight,height("converter_history_0"),0f)}
 @Test fun recallAndInvalidClearStayExplicit(){start();unfold();recall();large();rule.onNodeWithTag("converter_recall_confirm",true).assertExists();click("converter_recall_confirm");value().assertTextEquals("1");rule.onNodeWithTag("converter_result",true).assertDoesNotExist();rule.onNodeWithTag("converter_recalled",true).assertExists();large(false);rule.onNodeWithTag("converter_recalled",true).assertExists();hit("converter_convert");verify(CallConverter.convert("1","m","ft"));input("converter_input","1,000");hit("converter_convert");rule.onNodeWithTag("converter_error",true).assertExists();large();rule.onNodeWithTag("converter_error",true).assertExists();rule.onNodeWithTag("converter_history_count",true).assertTextEquals("Session history: 3 / 10");hit("converter_clear");value().assertTextEquals("");rule.onNodeWithTag("converter_result",true).assertDoesNotExist()}
 @Test fun settingsOnePreferenceAndFinder(){seed();mount{CallConverterPage{}};val before=LdApp.settings.value;hit("converter_large_result_switch");await{LdApp.settings.value.converterLargeResult};assertEquals(before.copy(converterLargeResult=true),LdApp.settings.value);move("converter_large_result_switch");saveShot(rule,"CONV524-settings-on");hit("converter_large_result_switch");await{!LdApp.settings.value.converterLargeResult};assertEquals(before,LdApp.settings.value);assertTrue(SettingsFinder.search("Larger conversion result").any{it.id=="converter-large-result"&&it.route=="callconverter"})}
}
@RunWith(RobolectricTestRunner::class) @Config(sdk=[34],qualifiers="w320dp-h640dp-xhdpi") @GraphicsMode(GraphicsMode.Mode.NATIVE)
class ConverterLargeResultNightUiTest:ConverterLargeResultFixture(){
 @Test fun longNumberNightLargeFullTextAndCallControls(){live(true);large();input("converter_input","12345.123456");hit("converter_convert");verify(CallConverter.convert("12345.123456","m","ft"));move("converter_result_source");saveShot(rule,"CONV524-night-value");move("converter_value_scroll");val before=rule.onNodeWithTag("converter_value",true).getUnclippedBoundsInRoot().left;rule.onNodeWithTag("converter_value_scroll",true).performTouchInput{swipeLeft()};settle();val after=rule.onNodeWithTag("converter_value",true).getUnclippedBoundsInRoot().left;assertTrue(after<before);verify(CallConverter.convert("12345.123456","m","ft"));move("converter_result_source");saveShot(rule,"CONV524-night-note");rule.onNodeWithTag("converter_result_rounding",true).assertIsDisplayed();rule.onNodeWithTag("end_call",true).assertIsDisplayed();assertTrue(Repo.notesFor(ctx,"+919876543210").isEmpty())}
}
